    printf("全部参与挑选 → 最小是下标 %d（权值 %d），次小是下标 %d（权值 %d）\n",
           s1, HT[s1].weight, s2, HT[s2].weight);
    printf("（应该是 4 号权值 1、2 号权值 2）\n\n");

    /* 给 4 号安个父亲，它就不该再被挑中 */
    HT[4].parent = 6;
    SelectTwoMin(HT, 5, &s1, &s2);
    printf("给 4 号安上父亲后再挑 → 最小 %d（权值 %d），次小 %d（权值 %d）\n",
