/* ======== [已给出] 模块 03 HuffmanCreate ======== */

void HuffmanCreate(HuffmanTree *HT, const int weights[], int n)
{
    int m;
    int i;
    int s1, s2;

    if (n <= 1)
    {
        *HT = NULL;
        return;
    }

    m = 2 * n - 1;
    *HT = (HuffmanTree)malloc((m + 1) * sizeof(HTNode));

    for (i = 1; i <= n; i++)
    {
        (*HT)[i].weight = weights[i - 1];
        (*HT)[i].parent = 0;
        (*HT)[i].left = 0;
        (*HT)[i].right = 0;
    }

    for (i = n + 1; i <= m; i++)
    {
        (*HT)[i].weight = 0;
        (*HT)[i].parent = 0;
        (*HT)[i].left = 0;
        (*HT)[i].right = 0;
    }

    for (i = n + 1; i <= m; i++)
    {
        SelectTwoMin(*HT, i - 1, &s1, &s2);

        (*HT)[s1].parent = i;
        (*HT)[s2].parent = i;

        (*HT)[i].left = s1;
        (*HT)[i].right = s2;

        (*HT)[i].weight = (*HT)[s1].weight + (*HT)[s2].weight;
    }

}

/* ======== [已给出] 模块 04 HuffmanCodes ======== */

void HuffmanCodes(HuffmanTree HT, int n, HuffmanCode *HC)
{
